"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([[19326],{66980:e=>{e.exports=JSON.parse('{"tag":{"label":"Rescue","permalink":"/docs/tags/rescue","allTagsPath":"/docs/tags","count":20,"items":[{"id":"rescue-resources/so-you-want-to-run-a-rescue/establish-your-network","title":"Establish Your Network: The Power of Community","description":"A guide for animal rescues on the importance of building a strong network of volunteers, foster homes, veterinary partners, and community supporters.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/establish-your-network"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/getting-started","title":"Getting Started: The Foundation of Your Rescue","description":"The essential first steps to starting an animal rescue, including defining your mission, building a board, and navigating the legal process of becoming a 501(c)(3) nonprofit.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/getting-started"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/getting-supplies","title":"Getting Supplies: Equipping Your Rescue for Success","description":"A practical guide for new animal rescues on how to acquire the essential supplies needed to care for animals, from food and housing to medical equipment.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/getting-supplies"},{"id":"general-care/getting-a-pet/foundpet","title":"Help, I Found a Pet!","description":"* Is it a pet?","permalink":"/docs/general-care/getting-a-pet/foundpet"},{"id":"general-care/getting-a-pet/rehome","title":"How to Rehome a Pet","description":"We all hope to keep our pets forever, but sometimes life happens and unfortunately, we have to find a new home for our pets. Here is some advice for safely rehoming your pets.","permalink":"/docs/general-care/getting-a-pet/rehome"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/level-up-your-skills","title":"Level Up Your Skills: From Passion to Profession","description":"A guide for established animal rescues on how to level up their skills in advanced medical care, fundraising, and nonprofit management for long-term sustainability.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/level-up-your-skills"},{"id":"rescue-resources/Report/report-ct","title":"Report Pet Store Neglect in Connecticut","description":"Kawaii illustration of a guinea pig in a pet store with a caring person ready to report neglect in Connecticut","permalink":"/docs/rescue-resources/Report/report-ct"},{"id":"rescue-resources/Report/report-ma","title":"Report Pet Store Neglect in Massachusetts","description":"Kawaii illustration of a rabbit in a pet store with a caring advocate in Massachusetts","permalink":"/docs/rescue-resources/Report/report-ma"},{"id":"rescue-resources/Report/report-nh","title":"Report Pet Store Neglect in New Hampshire","description":"Kawaii illustration of a hamster in a pet store with a caring advocate in New Hampshire","permalink":"/docs/rescue-resources/Report/report-nh"},{"id":"rescue-resources/Report/report-nj","title":"Report Pet Store Neglect in New Jersey","description":"Kawaii illustration of a guinea pig in a pet store with a caring advocate in New Jersey","permalink":"/docs/rescue-resources/Report/report-nj"},{"id":"rescue-resources/Report/report-ny","title":"Report Pet Store Neglect in New York","description":"Kawaii illustration of a rat in a pet store with a caring advocate in New York","permalink":"/docs/rescue-resources/Report/report-ny"},{"id":"rescue-resources/Report/report-pa","title":"Report Pet Store Neglect in Pennsylvania","description":"Kawaii illustration of a chinchilla in a pet store with a caring advocate in Pennsylvania","permalink":"/docs/rescue-resources/Report/report-pa"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/vets","title":"Rescue and Veterinary Care: What You Owe the Animals","description":"Kawaii illustration of a veterinarian examining a guinea pig with a rescue volunteer watching","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/vets"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/the-true-cost","title":"So You Want to Run a Rescue? Part 1: The True Cost of Saving Lives","description":"Part 1 of a series on running an animal rescue, focusing on the significant and often underestimated financial costs involved, from veterinary bills to daily supplies.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/the-true-cost"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/the-emotional-gauntlet","title":"So You Want to Run a Rescue? Part 2: The Emotional Gauntlet","description":"Part 2 of a series on running an animal rescue, exploring the intense emotional challenges, including compassion fatigue, burnout, and the difficulty of making life-and-death decisions.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/the-emotional-gauntlet"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/the-physical-toll","title":"So You Want to Run a Rescue? Part 3: The Physical Toll & Unseen Labor","description":"Part 3 of a series on running an animal rescue, detailing the intense, often invisible physical labor and the 24/7 time commitment that rescue work demands.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/the-physical-toll"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/building-a-sustainable-future","title":"So You Want to Run a Rescue? Part 4: Building a Sustainable Future","description":"Part 4 of a series on running an animal rescue, focusing on strategies for building a sustainable organization that can survive long-term, including effective fundraising, volunteer management, and preventing burnout.","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/building-a-sustainable-future"},{"id":"general-care/sensitive-topics/animal-hoarding","title":"The Shadow of Compassion: Understanding and Addressing Animal Hoarding","description":"Animal hoarding is a complex and tragic issue that sits at the intersection of animal welfare, public health, and mental illness. It is not born from a place of malice, but often from a deeply misguided sense of love and a compulsive need to \u201csave\u201d animals. This article aims to shed light on this sensitive topic with the delicacy it deserves, providing guidance for individuals who may be struggling, as well as for rescues navigating these difficult situations.","permalink":"/docs/general-care/sensitive-topics/animal-hoarding"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/transparency","title":"Transparency Is Not Optional \u2014 It\u2019s Foundational","description":"Kawaii illustration of a rescue coordinator sharing information openly with supporters","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/transparency"},{"id":"rescue-resources/so-you-want-to-run-a-rescue/budget","title":"Why Budgeting is Important","description":"Kawaii illustration of rescue budget planning with income and expense categories","permalink":"/docs/rescue-resources/so-you-want-to-run-a-rescue/budget"}],"unlisted":false}}')}}]);